import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.optim as optim

from sklearn.tree import DecisionTreeRegressor
from sklearn.base import BaseEstimator, ClassifierMixin
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler
from sklearn.decomposition import PCA
from sklearn.metrics import (
    accuracy_score, roc_auc_score, precision_score,
    recall_score, f1_score, confusion_matrix, log_loss
)
from sklearn.utils.validation import check_X_y, check_array
from imblearn.over_sampling import SMOTE

import warnings
warnings.filterwarnings("ignore")

# ==========================================================
# 🔴 1️⃣ Deep Feature Extractor (GPU Enabled)
# ==========================================================

class DeepFeatureExtractor(nn.Module):
    def __init__(self, input_dim, embedding_dim=16):
        super(DeepFeatureExtractor, self).__init__()

        self.feature_net = nn.Sequential(
            nn.Linear(input_dim, 64),
            nn.BatchNorm1d(64),
            nn.ReLU(),
            nn.Dropout(0.3),

            nn.Linear(64, 32),
            nn.ReLU(),

            nn.Linear(32, embedding_dim)
        )

        self.classifier = nn.Linear(embedding_dim, 1)

    def forward(self, x):
        embedding = self.feature_net(x)
        logits = self.classifier(embedding)
        return logits, embedding


# ==========================================================
# 🔴 2️⃣ Reflective Gradient Boosting Core
# ==========================================================

class IntensiveGBMClassifier(BaseEstimator, ClassifierMixin):

    def __init__(
        self,
        n_estimators=100,
        learning_rate=0.05,
        max_depth=3,
        min_samples_leaf=10,
        alpha=0.8,
        beta=0.2,
        random_state=42
    ):
        self.n_estimators = n_estimators
        self.learning_rate = learning_rate
        self.max_depth = max_depth
        self.min_samples_leaf = min_samples_leaf
        self.alpha = alpha
        self.beta = beta
        self.random_state = random_state

    def _sigmoid(self, x):
        return 1 / (1 + np.exp(-x))

    def fit(self, X, y):

        X, y = check_X_y(X, y)
        np.random.seed(self.random_state)

        self.trees_ = []
        self.base_prediction_ = np.log(np.mean(y) / (1 - np.mean(y)))
        y_pred = np.full(len(y), self.base_prediction_)

        prev_gradient = np.zeros_like(y)

        for _ in range(self.n_estimators):

            prob = self._sigmoid(y_pred)
            gradient = prob - y

            # Reflective Gradient Memory (stable)
            reflective_gradient = (
                self.alpha * gradient +
                self.beta * prev_gradient
            )

            prev_gradient = gradient.copy()

            tree = DecisionTreeRegressor(
                max_depth=self.max_depth,
                min_samples_leaf=self.min_samples_leaf,
                random_state=self.random_state
            )

            tree.fit(X, -reflective_gradient)
            update = tree.predict(X)

            y_pred += self.learning_rate * update
            self.trees_.append(tree)

        return self

    def predict_proba(self, X):
        X = check_array(X)
        y_pred = np.full(len(X), self.base_prediction_)

        for tree in self.trees_:
            y_pred += self.learning_rate * tree.predict(X)

        prob = self._sigmoid(y_pred)
        return np.vstack([1 - prob, prob]).T

    def predict(self, X):
        return (self.predict_proba(X)[:, 1] > 0.5).astype(int)


# ==========================================================
# 🔴 3️⃣ Full Training Pipeline
# ==========================================================

if __name__ == "__main__":

    # ------------------------------------------------------
    # Load Dataset
    # ------------------------------------------------------
    df = pd.read_csv("/content/Vibration_Dataset.csv")

    X = df.iloc[:, :-8].values
    y = df.iloc[:, -3].values

    # ------------------------------------------------------
    # Train/Test Split
    # ------------------------------------------------------
    X_train, X_test, y_train, y_test = train_test_split(
        X, y,
        test_size=0.3,
        random_state=42,
        stratify=y
    )

    # ------------------------------------------------------
    # Scaling
    # ------------------------------------------------------
    scaler = StandardScaler()
    X_train = scaler.fit_transform(X_train)
    X_test = scaler.transform(X_test)

    # ------------------------------------------------------
    # PCA (retain 95% variance)
    # ------------------------------------------------------
    pca = PCA(n_components=0.95, random_state=42)
    X_train = pca.fit_transform(X_train)
    X_test = pca.transform(X_test)

    print("Original Feature Dim :", X.shape[1])
    print("After PCA Dim        :", X_train.shape[1])

    # ------------------------------------------------------
    # SMOTE (Train Only)
    # ------------------------------------------------------
    smote = SMOTE(random_state=42)
    X_train, y_train = smote.fit_resample(X_train, y_train)

    print("After SMOTE Samples  :", X_train.shape[0])

    # ======================================================
    # 🔥 Deep Feature Extraction
    # ======================================================

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    model_nn = DeepFeatureExtractor(X_train.shape[1]).to(device)
    optimizer = optim.Adam(model_nn.parameters(), lr=0.003)
    criterion = nn.BCEWithLogitsLoss()

    X_tensor = torch.FloatTensor(X_train).to(device)
    y_tensor = torch.FloatTensor(y_train.reshape(-1, 1)).to(device)

    for epoch in range(100):
        optimizer.zero_grad()
        logits, embedding = model_nn(X_tensor)
        loss = criterion(logits, y_tensor)
        loss.backward()
        optimizer.step()

    # Extract deep embeddings
    with torch.no_grad():
        _, train_embed = model_nn(X_tensor)
        train_embed = train_embed.cpu().numpy()

        X_test_tensor = torch.FloatTensor(X_test).to(device)
        _, test_embed = model_nn(X_test_tensor)
        test_embed = test_embed.cpu().numpy()

    # Concatenate PCA features + deep embeddings
    X_train_final = np.hstack([X_train, train_embed])
    X_test_final = np.hstack([X_test, test_embed])

    print("Final Feature Dimension:", X_train_final.shape[1])

    # ======================================================
    # 🚀 Train IntensiveGBM
    # ======================================================

    igbm = IntensiveGBMClassifier(
        n_estimators=100,
        learning_rate=0.05,
        max_depth=3
    )

    igbm.fit(X_train_final, y_train)

    # ------------------------------------------------------
    # Evaluation
    # ------------------------------------------------------

    y_pred = igbm.predict(X_test_final)
    y_prob = igbm.predict_proba(X_test_final)[:, 1]

    acc = accuracy_score(y_test, y_pred)
    auc = roc_auc_score(y_test, y_prob)
    precision = precision_score(y_test, y_pred)
    recall = recall_score(y_test, y_pred)
    f1 = f1_score(y_test, y_pred)

    tn, fp, fn, tp = confusion_matrix(y_test, y_pred).ravel()
    specificity = tn / (tn + fp)

    print("\n📊 IntensiveGBM Results")
    print("Accuracy     :", acc)
    print("ROC-AUC      :", auc)
    print("Precision    :", precision)
    print("Recall       :", recall)
    print("Specificity  :", specificity)
    #print("F1-Score     :", f1)
    print("LogLoss      :", log_loss(y_test, y_prob))

