    # Load Dataset
    # ------------------------------------------------------
    df = pd.read_csv("/content/Vibration_Dataset.csv")

    X = df.iloc[:, :-8].values
    y = df.iloc[:, -8].values

    # ------------------------------------------------------
    # Train/Test Split
    # ------------------------------------------------------
    X_train, X_test, y_train, y_test = train_test_split(
        X, y,
        test_size=0.3,
        random_state=42,
        stratify=y
    )

    # ------------------------------------------------------
