# ============================================================
# 🔥 Meta-Cognitive Entropic Gradient Boosting (MEGB_v2)
# Full Experimental Pipeline
# ============================================================

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

from sklearn.tree import DecisionTreeRegressor
from sklearn.metrics import *
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler


# ============================================================
# 🧠 MEGB_v2 MODEL
# ============================================================

class MEGB_v2:
    def __init__(
        self,
        n_estimators=200,
        learning_rate=0.05,
        max_depth=4,
        gamma_entropy=3.0,
        lambda_uncertainty=4.0,
        lambda_entropy_reg=0.5,
        rho_memory=0.9,
        stability_mu=0.01,
        early_stopping_rounds=20,
        random_state=42
    ):
        self.n_estimators = n_estimators
        self.learning_rate = learning_rate
        self.max_depth = max_depth
        self.gamma_entropy = gamma_entropy
        self.lambda_uncertainty = lambda_uncertainty
        self.lambda_entropy_reg = lambda_entropy_reg
        self.rho_memory = rho_memory
        self.stability_mu = stability_mu
        self.early_stopping_rounds = early_stopping_rounds
        self.random_state = random_state

        self.trees = []
        self.F0 = None
        self.best_iteration = None
        self.train_losses = []

    def _sigmoid(self, x):
        return 1 / (1 + np.exp(-x))

    def _gradient_entropy(self, g):
        p = np.abs(g)
        p = p / (np.sum(p) + 1e-12)
        return -np.sum(p * np.log(p + 1e-12))

    def fit(self, X, y, X_val=None, y_val=None):

        np.random.seed(self.random_state)
        n_samples = X.shape[0]

        pos_ratio = np.clip(np.mean(y), 1e-6, 1 - 1e-6)
        self.F0 = np.log(pos_ratio / (1 - pos_ratio))
        F = np.full(n_samples, self.F0)

        g_prev = np.zeros(n_samples)
        m_t = np.zeros(n_samples)

        best_loss = np.inf
        patience = 0

        for t in range(self.n_estimators):

            p = self._sigmoid(F)
            g = y - p

            H = self._gradient_entropy(g)
            alpha = 1 / (1 + np.exp(-self.gamma_entropy * H))

            m_t = self.rho_memory * m_t + (1 - self.rho_memory) * g

            norm_g = np.linalg.norm(g)
            norm_prev = np.linalg.norm(g_prev)
            norm_m = np.linalg.norm(m_t)

            total_norm = norm_g + norm_prev + norm_m + 1e-12

            beta = norm_prev / total_norm
            delta = norm_m / total_norm
            alpha = alpha / (alpha + beta + delta + 1e-12)

            g_final = alpha*g + beta*g_prev + delta*m_t

            g_final -= self.stability_mu * np.var(g)

            uncertainty = np.abs(0.5 - p)
            weights = 1 + self.lambda_uncertainty * (uncertainty ** 2)

            tree = DecisionTreeRegressor(
                max_depth=self.max_depth,
                random_state=self.random_state
            )

            tree.fit(X, g_final, sample_weight=weights)
            h = tree.predict(X)

            shrink = np.exp(-self.lambda_entropy_reg * H)
            h *= shrink

            F += self.learning_rate * h
            self.trees.append(tree)

            g_prev = g.copy()

            train_loss = log_loss(y, self._sigmoid(F))
            self.train_losses.append(train_loss)

            if X_val is not None:
                val_pred = self._predict_internal(X_val)
                val_loss = log_loss(y_val, val_pred)

                if val_loss < best_loss:
                    best_loss = val_loss
                    self.best_iteration = t
                    patience = 0
                else:
                    patience += 1

                if patience >= self.early_stopping_rounds:
                    print(f"Early stopping at iteration {t}")
                    break

        return self

    def _predict_internal(self, X):
        F = np.full(X.shape[0], self.F0)
        for tree in self.trees:
            F += self.learning_rate * tree.predict(X)
        return self._sigmoid(F)

    def predict_proba(self, X):
        p = self._predict_internal(X)
        return np.vstack([1 - p, p]).T

    def predict(self, X):
        return (self._predict_internal(X) >= 0.5).astype(int)


# ============================================================
# 📊 DATA PIPELINE
# ============================================================

df = pd.read_csv("/content/Vibration_Dataset.csv")

X = df.iloc[:, :-8].values
y = df.iloc[:, -1].values

scaler = StandardScaler()
X = scaler.fit_transform(X)

X_temp, X_test, y_temp, y_test = train_test_split(
    X, y, test_size=0.3, random_state=42
)

X_train, X_val, y_train, y_val = train_test_split(
    X_temp, y_temp, test_size=0.2, random_state=42
)

# ============================================================
# 🚀 TRAIN MODEL
# ============================================================

model = MEGB_v2(
    n_estimators=300,
    learning_rate=0.05,
    max_depth=4,
    gamma_entropy=3.0,
    lambda_uncertainty=4.0,
    lambda_entropy_reg=0.5,
    rho_memory=0.9,
    stability_mu=0.01
)

model.fit(X_train, y_train, X_val, y_val)

# ============================================================
# 📈 EVALUATION
# ============================================================

y_pred = model.predict(X_test)
y_prob = model.predict_proba(X_test)[:, 1]

accuracy = accuracy_score(y_test, y_pred)
precision = precision_score(y_test, y_pred)
recall = recall_score(y_test, y_pred)
f1 = f1_score(y_test, y_pred)
roc_auc = roc_auc_score(y_test, y_prob)
ll = log_loss(y_test, y_prob)

tn, fp, fn, tp = confusion_matrix(y_test, y_pred).ravel()
specificity = tn / (tn + fp)

print("\n🚀 MEGB_v2 Results")
print("Accuracy     :", accuracy)
print("ROC-AUC      :", roc_auc)
print("Precision    :", precision)
print("Recall       :", recall)
print("Specificity  :", specificity)
print("F1-Score     :", f1)
print("LogLoss      :", ll)

