# ============================================================
# 🚀 RRGBNet v3 – Enhanced with SCAR Attention
# SMOTE + PCA + XGBoost + Reflective Residual DL
# Entropy-Adaptive Fusion + Label Smoothing
# ============================================================

# =========================
# 1️⃣ Imports
# =========================
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import torch
import torch.nn as nn
import torch.optim as optim

from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler, LabelEncoder, label_binarize
from sklearn.decomposition import PCA
from sklearn.metrics import (
    accuracy_score, precision_score, recall_score,
    f1_score, log_loss, confusion_matrix,
    roc_curve, auc
)

from imblearn.over_sampling import SMOTE
from xgboost import XGBClassifier

# =========================
# 2️⃣ Load Dataset
# =========================
df = pd.read_csv("/content/Vibration_Dataset.csv")

X = df.iloc[:, :-8].values
y = df.iloc[:, -4].values

if y.dtype == 'object':
    le = LabelEncoder()
    y = le.fit_transform(y)

num_classes = len(np.unique(y))

# =========================
# 3️⃣ Train-Test Split
# =========================
X_train, X_test, y_train, y_test = train_test_split(
    X, y, test_size=0.3, random_state=42, stratify=y
)

# =========================
# 4️⃣ Standardization
# =========================
scaler = StandardScaler()
X_train = scaler.fit_transform(X_train)
X_test = scaler.transform(X_test)

# =========================
# 5️⃣ SMOTE (Only Training)
# =========================
smote = SMOTE(random_state=42)
X_train, y_train = smote.fit_resample(X_train, y_train)

print("After SMOTE distribution:", np.bincount(y_train))

# =========================
# 6️⃣ PCA (95% Variance)
# =========================
pca = PCA(n_components=0.95)
X_train = pca.fit_transform(X_train)
X_test = pca.transform(X_test)

print("Reduced Dimension:", X_train.shape[1])

# Convert to Torch
X_train_tensor = torch.FloatTensor(X_train)
y_train_tensor = torch.LongTensor(y_train)
X_test_tensor = torch.FloatTensor(X_test)

input_dim = X_train.shape[1]

# ============================================================
# 🔥 7️⃣ SCAR: Self-Calibrated Attention Reweighting
# ============================================================
class SCARLayer(nn.Module):
    def __init__(self, input_dim):
        super().__init__()
        self.attention = nn.Sequential(
            nn.Linear(input_dim, input_dim // 2),
            nn.ReLU(),
            nn.Linear(input_dim // 2, input_dim),
            nn.Sigmoid()
        )

    def forward(self, x):
        weights = self.attention(x)
        return x * weights


# ============================================================
# 🚀 8️⃣ Reflective Residual Network + SCAR
# ============================================================
class ReflectiveResidualNet(nn.Module):
    def __init__(self, input_dim, num_classes):
        super().__init__()

        self.scar = SCARLayer(input_dim)

        self.fc1 = nn.Linear(input_dim, 256)
        self.bn1 = nn.BatchNorm1d(256)

        self.fc2 = nn.Linear(256, 128)
        self.bn2 = nn.BatchNorm1d(128)

        self.residual = nn.Linear(input_dim, 128)

        self.fc3 = nn.Linear(128, 64)
        self.fc_out = nn.Linear(64, num_classes)

        self.dropout = nn.Dropout(0.4)

    def forward(self, x):

        x = self.scar(x)   # 🔥 Attention applied

        identity = self.residual(x)

        x = torch.relu(self.bn1(self.fc1(x)))
        x = self.dropout(x)

        x = torch.relu(self.bn2(self.fc2(x)))
        x = x + identity

        x = torch.relu(self.fc3(x))
        x = self.fc_out(x)

        return x


model = ReflectiveResidualNet(input_dim, num_classes)

# 🔥 Label Smoothing
criterion = nn.CrossEntropyLoss(label_smoothing=0.05)
optimizer = optim.Adam(model.parameters(), lr=0.0008)

# ============================================================
# 9️⃣ Train Deep Model
# ============================================================
epochs = 80
train_losses = []

for epoch in range(epochs):

    model.train()
    optimizer.zero_grad()

    outputs = model(X_train_tensor)
    loss = criterion(outputs, y_train_tensor)

    loss.backward()
    optimizer.step()

    train_losses.append(loss.item())

    if (epoch+1) % 10 == 0:
        print(f"Epoch [{epoch+1}/{epochs}] Loss: {loss.item():.4f}")

# ============================================================
# 🔟 Gradient Boosting Path
# ============================================================
gb_model = XGBClassifier(
    n_estimators=600,
    max_depth=7,
    learning_rate=0.03,
    subsample=0.9,
    colsample_bytree=0.9,
    eval_metric='mlogloss',
    random_state=42
)

gb_model.fit(X_train, y_train)

gb_test_probs = gb_model.predict_proba(X_test)

# ============================================================
# 1️⃣1️⃣ Deep Model Predictions
# ============================================================
model.eval()
with torch.no_grad():
    dl_logits = model(X_test_tensor)

dl_test_probs = torch.softmax(dl_logits, dim=1).numpy()

# ============================================================
# 1️⃣2️⃣ Entropy-Adaptive Fusion
# ============================================================
def entropy(p):
    return -np.sum(p * np.log(p + 1e-9), axis=1)

gb_entropy = entropy(gb_test_probs)
dl_entropy = entropy(dl_test_probs)

gb_weight = 1 / (gb_entropy + 1e-6)
dl_weight = 1 / (dl_entropy + 1e-6)

gb_weight = gb_weight / (gb_weight + dl_weight)
dl_weight = 1 - gb_weight

final_probs = (
    gb_test_probs * gb_weight[:, None] +
    dl_test_probs * dl_weight[:, None]
)

final_preds = np.argmax(final_probs, axis=1)

# ============================================================
# 1️⃣3️⃣ Evaluation
# ============================================================
accuracy = accuracy_score(y_test, final_preds)
precision = precision_score(y_test, final_preds, average='weighted')
recall = recall_score(y_test, final_preds, average='weighted')
f1 = f1_score(y_test, final_preds, average='weighted')
logloss = log_loss(y_test, final_probs)

print("\n🚀 RRGBNet v3 Results")
print("Accuracy  :", accuracy)
print("Precision :", precision)
print("Recall    :", recall)
print("F1-Score  :", f1)
print("LogLoss   :", logloss)

# ============================================================
# 🎨 Confusion Matrix
# ============================================================
cm = confusion_matrix(y_test, final_preds)

plt.figure(figsize=(6,5))
sns.heatmap(cm, annot=True, fmt="d", cmap="magma")
plt.title("RRGBNet v3 Confusion Matrix")
plt.xlabel("Predicted")
plt.ylabel("Actual")
plt.tight_layout()
plt.show()

# ============================================================
# 📉 Training Loss
# ============================================================
plt.figure(figsize=(7,5))
plt.plot(train_losses)
plt.title("RRGBNet v3 Training Loss")
plt.xlabel("Epoch")
plt.ylabel("Loss")
plt.tight_layout()
plt.show()

# ============================================================
# 📈 ROC Curve
# ============================================================
if num_classes == 2:
    y_prob = final_probs[:, 1]
    fpr, tpr, _ = roc_curve(y_test, y_prob)
    roc_auc = auc(fpr, tpr)

    plt.figure(figsize=(6,5))
    plt.plot(fpr, tpr, label=f"AUC = {roc_auc:.4f}")
    plt.plot([0,1], [0,1], linestyle='--')
    plt.title("RRGBNet v3 ROC Curve")
    plt.xlabel("FPR")
    plt.ylabel("TPR")
    plt.legend()
    plt.tight_layout()
    plt.show()
else:
    y_test_bin = label_binarize(y_test, classes=np.unique(y_test))

    plt.figure(figsize=(6,5))
    for i in range(num_classes):
        fpr, tpr, _ = roc_curve(y_test_bin[:, i], final_probs[:, i])
        roc_auc = auc(fpr, tpr)
        plt.plot(fpr, tpr, label=f"Class {i} AUC = {roc_auc:.3f}")

    plt.plot([0,1], [0,1], linestyle='--')
    plt.title("RRGBNet v3 Multi-Class ROC")
    plt.xlabel("FPR")
    plt.ylabel("TPR")
    plt.legend()
    plt.tight_layout()
    plt.show()

"""**Thermal Drift**"""

