# ============================================================
# 🚀 RRGBNet v5 – Triple Hybrid with SCAR-DL + XGBoost + LightGBM
# Polynomial Features + Entropy Sample Weighting + Meta Fusion
# ============================================================

# =========================
# 1️⃣ Imports
# =========================
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import torch
import torch.nn as nn
import torch.optim as optim

from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler, LabelEncoder, label_binarize, PolynomialFeatures
from sklearn.decomposition import PCA
from sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score, log_loss, confusion_matrix, roc_curve, auc

from imblearn.over_sampling import SMOTE
from xgboost import XGBClassifier
from lightgbm import LGBMClassifier

# =========================
# 2️⃣ Load Dataset
# =========================
df = pd.read_csv("/content/Vibration_Dataset.csv")

X = df.iloc[:, :-8].values
y = df.iloc[:, -1].values  # adjust according to target column

if y.dtype == 'object':
    le = LabelEncoder()
    y = le.fit_transform(y)

num_classes = len(np.unique(y))

# =========================
# 3️⃣ Train-Test Split
# =========================
X_train, X_test, y_train, y_test = train_test_split(
    X, y, test_size=0.3, random_state=42, stratify=y
)

# =========================
# 4️⃣ Standardization + Polynomial Expansion
# =========================
poly = PolynomialFeatures(degree=2, interaction_only=True, include_bias=False)
X_train = poly.fit_transform(X_train)
X_test = poly.transform(X_test)

scaler = StandardScaler()
X_train = scaler.fit_transform(X_train)
X_test = scaler.transform(X_test)

# =========================
# 5️⃣ SMOTE (only training)
# =========================
smote = SMOTE(random_state=42)
X_train, y_train = smote.fit_resample(X_train, y_train)
print("After SMOTE distribution:", np.bincount(y_train))

# =========================
# 6️⃣ PCA
# =========================
pca = PCA(n_components=0.95)
X_train = pca.fit_transform(X_train)
X_test = pca.transform(X_test)
print("Reduced Dimension:", X_train.shape[1])

# Torch tensors
X_train_tensor = torch.FloatTensor(X_train)
y_train_tensor = torch.LongTensor(y_train)
X_test_tensor = torch.FloatTensor(X_test)

input_dim = X_train.shape[1]

# =========================
# 7️⃣ SCAR Attention Layer
# =========================
class SCARLayer(nn.Module):
    def __init__(self, input_dim):
        super().__init__()
        self.attention = nn.Sequential(
            nn.Linear(input_dim, input_dim // 2),
            nn.ReLU(),
            nn.Linear(input_dim // 2, input_dim),
            nn.Sigmoid()
        )
    def forward(self, x):
        weights = self.attention(x)
        return x * weights

# =========================
# 8️⃣ Reflective Residual Network
# =========================
class ReflectiveResidualNet(nn.Module):
    def __init__(self, input_dim, num_classes):
        super().__init__()
        self.scar = SCARLayer(input_dim)
        self.fc1 = nn.Linear(input_dim, 256)
        self.bn1 = nn.BatchNorm1d(256)
        self.fc2 = nn.Linear(256, 128)
        self.bn2 = nn.BatchNorm1d(128)
        self.residual = nn.Linear(input_dim, 128)
        self.fc3 = nn.Linear(128, 64)
        self.fc_out = nn.Linear(64, num_classes)
        self.dropout = nn.Dropout(0.4)

    def forward(self, x):
        x = self.scar(x)
        identity = self.residual(x)
        x = torch.relu(self.bn1(self.fc1(x)))
        x = self.dropout(x)
        x = torch.relu(self.bn2(self.fc2(x)))
        x = x + identity
        x = torch.relu(self.fc3(x))
        x = self.fc_out(x)
        return x

model = ReflectiveResidualNet(input_dim, num_classes)

# =========================
# 9️⃣ Training DL Model
# =========================
criterion = nn.CrossEntropyLoss(label_smoothing=0.05)
optimizer = optim.Adam(model.parameters(), lr=0.0008)
epochs = 80
train_losses = []

for epoch in range(epochs):
    model.train()
    optimizer.zero_grad()
    outputs = model(X_train_tensor)
    loss = criterion(outputs, y_train_tensor)
    loss.backward()
    optimizer.step()
    train_losses.append(loss.item())
    if (epoch+1) % 10 == 0:
        print(f"Epoch [{epoch+1}/{epochs}] Loss: {loss.item():.4f}")

# DL probabilities
model.eval()
with torch.no_grad():
    dl_train_probs = torch.softmax(model(X_train_tensor), dim=1).numpy()
    dl_test_probs = torch.softmax(model(X_test_tensor), dim=1).numpy()

# =========================
# 🔟 Compute Sample Weights (entropy-based) for boosting
# =========================
def entropy(p):
    return -np.sum(p * np.log(p + 1e-9), axis=1)

dl_train_entropy = entropy(dl_train_probs)
xgb_weights = 1 + dl_train_entropy
lgb_weights = 1 + dl_train_entropy

# =========================
# 1️⃣1️⃣ XGBoost Path
# =========================
xgb = XGBClassifier(
    n_estimators=600,
    max_depth=7,
    learning_rate=0.03,
    subsample=0.9,
    colsample_bytree=0.9,
    eval_metric='mlogloss',
    random_state=42
)
xgb.fit(X_train, y_train, sample_weight=xgb_weights)
xgb_probs = xgb.predict_proba(X_test)

# =========================
# 1️⃣2️⃣ LightGBM Path
# =========================
lgbm = LGBMClassifier(
    n_estimators=800,
    max_depth=-1,
    learning_rate=0.03,
    subsample=0.9,
    colsample_bytree=0.9,
    random_state=42
)
lgbm.fit(X_train, y_train, sample_weight=lgb_weights)
lgbm_probs = lgbm.predict_proba(X_test)

# =========================
# 1️⃣3️⃣ Meta-Learning Fusion Layer
# Small NN to learn optimal weights per sample
# =========================
class FusionNN(nn.Module):
    def __init__(self):
        super().__init__()
        self.fc = nn.Sequential(
            nn.Linear(num_classes*3, 64),
            nn.ReLU(),
            nn.Linear(64, 3),
            nn.Softmax(dim=1)
        )

    def forward(self, x):
        return self.fc(x)

fusion_model = FusionNN()
fusion_optimizer = optim.Adam(fusion_model.parameters(), lr=0.001)
fusion_criterion = nn.CrossEntropyLoss()

# Prepare concatenated probs for training fusion NN (on training data)
with torch.no_grad():
    dl_train_probs_t = torch.FloatTensor(dl_train_probs)
xgb_train_probs_t = torch.FloatTensor(xgb.predict_proba(X_train))
lgb_train_probs_t = torch.FloatTensor(lgbm.predict_proba(X_train))
fusion_input = torch.cat([dl_train_probs_t, xgb_train_probs_t, lgb_train_probs_t], dim=1)

# Train fusion NN briefly on training set
fusion_epochs = 20
fusion_labels = torch.LongTensor(y_train)
for epoch in range(fusion_epochs):
    fusion_optimizer.zero_grad()
    weights = fusion_model(fusion_input)
    # Weighted sum
    ensemble_probs = weights[:,0:1]*dl_train_probs_t + weights[:,1:2]*xgb_train_probs_t + weights[:,2:3]*lgb_train_probs_t
    loss = fusion_criterion(ensemble_probs, fusion_labels)
    loss.backward()
    fusion_optimizer.step()

# =========================
# 1️⃣4️⃣ Generate Final Ensemble Predictions
# =========================
with torch.no_grad():
    dl_probs_t = torch.FloatTensor(dl_test_probs)
    xgb_probs_t = torch.FloatTensor(xgb_probs)
    lgb_probs_t = torch.FloatTensor(lgbm_probs)

    fusion_input_test = torch.cat([dl_probs_t, xgb_probs_t, lgb_probs_t], dim=1)
    fusion_weights = fusion_model(fusion_input_test)
    final_probs = (fusion_weights[:,0:1]*dl_probs_t +
                   fusion_weights[:,1:2]*xgb_probs_t +
                   fusion_weights[:,2:3]*lgb_probs_t).numpy()

final_preds = np.argmax(final_probs, axis=1)

# =========================
# 1️⃣5️⃣ Evaluation
# =========================
accuracy = accuracy_score(y_test, final_preds)
precision = precision_score(y_test, final_preds, average='weighted')
recall = recall_score(y_test, final_preds, average='weighted')
f1 = f1_score(y_test, final_preds, average='weighted')
logloss = log_loss(y_test, final_probs)

print("\n🚀 RRGBNet v5 Results (Triple Hybrid + Meta Fusion)")
print("Accuracy  :", accuracy)
print("Precision :", precision)
print("Recall    :", recall)
print("F1-Score  :", f1)
print("LogLoss   :", logloss)

# =========================
# Confusion Matrix
# =========================
cm = confusion_matrix(y_test, final_preds)
plt.figure(figsize=(6,5))
sns.heatmap(cm, annot=True, fmt="d", cmap="magma")
plt.title("RRGBNet v5 Confusion Matrix")
plt.xlabel("Predicted")
plt.ylabel("Actual")
plt.tight_layout()
plt.show()

