# DL probabilities
model.eval()
with torch.no_grad():
    dl_train_probs = torch.softmax(model(X_train_tensor), dim=1).numpy()
    dl_test_probs = torch.softmax(model(X_test_tensor), dim=1).numpy()

# =========================
# 🔟 Compute Sample Weights (entropy-based) for boosting
# =========================
def entropy(p):
    return -np.sum(p * np.log(p + 1e-9), axis=1)

dl_train_entropy = entropy(dl_train_probs)
xgb_weights = 1 + dl_train_entropy
lgb_weights = 1 + dl_train_entropy

# =========================
# 1️⃣1️⃣ XGBoost Path
# =========================
xgb = XGBClassifier(
    n_estimators=600,
    max_depth=7,
    learning_rate=0.03,
    subsample=0.9,
    colsample_bytree=0.9,
    eval_metric='mlogloss',
    random_state=42
)
xgb.fit(X_train, y_train, sample_weight=xgb_weights)
xgb_probs = xgb.predict_proba(X_test)

# =========================
# 1️⃣2️⃣ LightGBM Path
# =========================
lgbm = LGBMClassifier(
    n_estimators=800,
    max_depth=-1,
    learning_rate=0.03,
    subsample=0.9,
    colsample_bytree=0.9,
    random_state=42
)
lgbm.fit(X_train, y_train, sample_weight=lgb_weights)
lgbm_probs = lgbm.predict_proba(X_test)

# =========================
# 1️⃣3️⃣ Meta-Learning Fusion Layer
# Small NN to learn optimal weights per sample
# =========================
class FusionNN(nn.Module):
    def __init__(self):
        super().__init__()
        self.fc = nn.Sequential(
            nn.Linear(num_classes*3, 64),
            nn.ReLU(),
            nn.Linear(64, 3),
            nn.Softmax(dim=1)
        )

    def forward(self, x):
        return self.fc(x)

fusion_model = FusionNN()
fusion_optimizer = optim.Adam(fusion_model.parameters(), lr=0.001)
fusion_criterion = nn.CrossEntropyLoss()

# Prepare concatenated probs for training fusion NN (on training data)
with torch.no_grad():
    dl_train_probs_t = torch.FloatTensor(dl_train_probs)
xgb_train_probs_t = torch.FloatTensor(xgb.predict_proba(X_train))
lgb_train_probs_t = torch.FloatTensor(lgbm.predict_proba(X_train))
fusion_input = torch.cat([dl_train_probs_t, xgb_train_probs_t, lgb_train_probs_t], dim=1)

# Train fusion NN briefly on training set
fusion_epochs = 20
fusion_labels = torch.LongTensor(y_train)
for epoch in range(fusion_epochs):
    fusion_optimizer.zero_grad()
    weights = fusion_model(fusion_input)
    # Weighted sum
    ensemble_probs = weights[:,0:1]*dl_train_probs_t + weights[:,1:2]*xgb_train_probs_t + weights[:,2:3]*lgb_train_probs_t
    loss = fusion_criterion(ensemble_probs, fusion_labels)
    loss.backward()
    fusion_optimizer.step()

# =========================
# 1️⃣4️⃣ Generate Final Ensemble Predictions
# =========================
with torch.no_grad():
    dl_probs_t = torch.FloatTensor(dl_test_probs)
    xgb_probs_t = torch.FloatTensor(xgb_probs)
    lgb_probs_t = torch.FloatTensor(lgbm_probs)

    fusion_input_test = torch.cat([dl_probs_t, xgb_probs_t, lgb_probs_t], dim=1)
    fusion_weights = fusion_model(fusion_input_test)
    final_probs = (fusion_weights[:,0:1]*dl_probs_t +
                   fusion_weights[:,1:2]*xgb_probs_t +
                   fusion_weights[:,2:3]*lgb_probs_t).numpy()

final_preds = np.argmax(final_probs, axis=1)

# =========================
# 1️⃣5️⃣ Evaluation
# =========================
accuracy = accuracy_score(y_test, final_preds)
precision = precision_score(y_test, final_preds, average='weighted')
recall = recall_score(y_test, final_preds, average='weighted')
f1 = f1_score(y_test, final_preds, average='weighted')
logloss = log_loss(y_test, final_probs)

print("\n🚀 RRGBNet v5 Results (Triple Hybrid + Meta Fusion)")
print("Accuracy  :", accuracy)
print("Precision :", precision)
print("Recall    :", recall)
print("F1-Score  :", f1)
print("LogLoss   :", logloss)

# =========================
# Confusion Matrix
# =========================
cm = confusion_matrix(y_test, final_preds)
plt.figure(figsize=(6,5))
sns.heatmap(cm, annot=True, fmt="d", cmap="magma")
plt.title("RRGBNet v5 Confusion Matrix")
plt.xlabel("Predicted")
plt.ylabel("Actual")
plt.tight_layout()
plt.show()

# =========================
# Training Loss Curve
# =========================
