fault_columns = [
    "Wiring Reversal",
    "Offset Bias",
    "Sensor Aging (Degradation)",
    "Thermal Drift",
    "Radiation-Induced Degradation",
    "High Noise Levels",
    "Gas Leakage",
    "Signal Drift"
]

# Function to convert multi-label row to single-label class
def multi_to_single_priority(row):
    for col in fault_columns:
        if row[col] == 1:
            return col  # assign the first active fault based on priority
    return "Normal"  # if no faults

# Apply the function to create a single-label column
