import numpy as np
import pandas as pd
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import accuracy_score, precision_score, recall_score
import lightgbm as lgb
from sklearn.neural_network import MLPRegressor

# -----------------------------
# Residual Memory Embedding Layer (RMEL)
# -----------------------------
class RMEL:
    def __init__(self, input_dim, hidden_dim=32):
        self.mlp = MLPRegressor(hidden_layer_sizes=(hidden_dim,), max_iter=150, random_state=42)

    def fit(self, X, residuals):
        # Train MLP to predict residuals
        self.mlp.fit(X, residuals)
        return self.transform(X, residuals)

    def transform(self, X, residuals):
        # Get embedding
        emb = self.mlp.predict(X).reshape(-1,1)
        Z = X + emb + 0.05*residuals.reshape(-1,1)
        return Z

# -----------------------------
# ResilientGBM++ 2.0
# -----------------------------
class ResilientGBMPlusPlus:
    def __init__(self, n_estimators=150, learning_rate=0.05, max_depth=6, residual_memory=3):
        self.n_estimators = n_estimators
        self.learning_rate = learning_rate
        self.max_depth = max_depth
        self.residual_memory = residual_memory
        self.model = None
        self.rm_layer = None

    # RGSS oversampling (simplified)
    def rgss_oversample(self, X, y, residuals):
        classes, counts = np.unique(y, return_counts=True)
        X_aug, y_aug = X.copy(), y.copy()

        for cls, count in zip(classes, counts):
            if count < 2:  # Skip extremely rare classes
                continue
            idx = np.where(y == cls)[0]
            top_idx = idx[np.argsort(np.abs(residuals[idx]))[-max(1,int(0.2*len(idx))):]]
            synth_samples, synth_labels = [], []
            for i in top_idx:
                j = np.random.choice(idx)
                lam = np.random.rand()
                x_new = X[i] + lam*(X[j]-X[i])
                synth_samples.append(x_new)
                synth_labels.append(cls)
            if synth_samples:
                X_aug = np.vstack([X_aug, np.array(synth_samples)])
                y_aug = np.hstack([y_aug, np.array(synth_labels)])
        return X_aug, y_aug

    # Fit method
    def fit(self, X, y):
        residuals = np.zeros(X.shape[0])
        self.rm_layer = RMEL(input_dim=X.shape[1])
        X_emb = self.rm_layer.fit(X, residuals)

        # Split train/validation (no stratify to avoid rare class issue)
        X_train_emb, X_val_emb, y_train_sub, y_val = train_test_split(
            X_emb, y, test_size=0.1, random_state=42
        )

        # Oversample minority classes
        X_train_aug, y_train_aug = self.rgss_oversample(X_train_emb, y_train_sub, residuals[:len(y_train_sub)])

        # LightGBM dataset
        lgb_train = lgb.Dataset(X_train_aug, y_train_aug)
        lgb_val = lgb.Dataset(X_val_emb, y_val, reference=lgb_train)

        params = {
    'objective': 'multiclass',
    'num_class': len(np.unique(y)),
    'learning_rate': 0.05,
    'max_depth': -1,  # allow deeper trees
    'num_leaves': 127,  # more expressive
    'min_data_in_leaf': 5,
    'feature_fraction': 0.9,
    'bagging_fraction': 0.8,
    'bagging_freq': 5,
    'reg_lambda': 1.0,
    'reg_alpha': 0.5,
    'class_weight': 'balanced',
    'metric': 'multi_logloss',
    'verbose': -1
}

        self.model = lgb.train(
            params,
            lgb_train,
            num_boost_round=self.n_estimators,
            valid_sets=[lgb_train, lgb_val],
            valid_names=['train','val'],
            callbacks=[lgb.early_stopping(stopping_rounds=20), lgb.log_evaluation(period=0)]
        )

    def predict(self, X):
        X_emb = self.rm_layer.transform(X, np.zeros(X.shape[0]))
        y_pred = self.model.predict(X_emb, num_iteration=self.model.best_iteration)
        if len(y_pred.shape) == 1:
            return (y_pred >= 0.5).astype(int)
        else:
            return np.argmax(y_pred, axis=1)

    def predict_proba(self, X):
        X_emb = self.rm_layer.transform(X, np.zeros(X.shape[0]))
        y_pred = self.model.predict(X_emb, num_iteration=self.model.best_iteration)
        if len(y_pred.shape) == 1:
            return np.vstack([1-y_pred, y_pred]).T
        else:
            return y_pred

# -----------------------------
# Load CSV
# -----------------------------
df = pd.read_csv("/content/Vibration Faults.csv")

# Features & target
