import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

from sklearn.preprocessing import StandardScaler
from sklearn.mixture import GaussianMixture
from sklearn.decomposition import PCA

# ==========================================
# 1. Load Dataset
# ==========================================
data = pd.read_csv("/content/Vibration_Faults.csv")

print("Dataset Shape:", data.shape)
print(data.head())

# ==========================================
# 2. Feature Scaling
# ==========================================
scaler = StandardScaler()
X_scaled = scaler.fit_transform(data)

# ==========================================
# 3. Determine Optimal Clusters (BIC)
# ==========================================
bic_scores = []
n_clusters_range = range(1, 11)

for k in n_clusters_range:
    gmm = GaussianMixture(n_components=k, random_state=42)
    gmm.fit(X_scaled)
    bic_scores.append(gmm.bic(X_scaled))

# Plot BIC scores
plt.figure(figsize=(8,5))
plt.plot(n_clusters_range, bic_scores, marker='o')
plt.xlabel("Number of Clusters")
plt.ylabel("BIC Score")
plt.title("BIC for Optimal Cluster Selection")
plt.show()

# ==========================================
# 4. Fit Final GMM Model
# ==========================================
optimal_clusters = 9   # adjust based on BIC curve

gmm = GaussianMixture(
    n_components=optimal_clusters,
    covariance_type='full',
    random_state=42
)

clusters = gmm.fit_predict(X_scaled)

# Add cluster labels
data['Cluster'] = clusters

print("\nCluster Counts:")
print(data['Cluster'].value_counts())

# ==========================================
# 5. PCA for Visualization
# ==========================================
pca = PCA(n_components=2)
X_pca = pca.fit_transform(X_scaled)

plt.figure(figsize=(8,6))

sns.scatterplot(
    x=X_pca[:,0],
    y=X_pca[:,1],
    hue=clusters,
    palette="viridis",
    s=80
)

plt.title("GMM Clustering Visualization (PCA Projection)")
plt.xlabel("PCA Component 1")
plt.ylabel("PCA Component 2")
plt.legend(title="Cluster")
plt.show()

# ==========================================
# 6. Cluster Statistics
# ==========================================
cluster_summary = data.groupby("Cluster").mean()

print("\nCluster Feature Means:")
print(cluster_summary)

# ==========================================
# 7. Save Results
# ==========================================
data.to_csv("GMM_Clustered_Vibration_Faults.csv", index=False)

