import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

from sklearn.preprocessing import StandardScaler
from sklearn.manifold import TSNE
from sklearn.decomposition import PCA
from sklearn.metrics import silhouette_score

import umap.umap_ as umap

# ---------------------------------------
# 1. LOAD DATASET
# ---------------------------------------
file_path = "/content/Vibration_Dataset.csv"
df = pd.read_csv(file_path)

print("Dataset shape:", df.shape)
print("\nFirst 5 rows:\n", df.head())

# ---------------------------------------
# 2. SPLIT FEATURES & LABELS
# ---------------------------------------
# Assuming last column is the label
X = df.iloc[:, :-8].values
y = df.iloc[:, -1].values

print("\nClass distribution:\n", pd.Series(y).value_counts())

# ---------------------------------------
# 3. STANDARDIZATION
# ---------------------------------------
scaler = StandardScaler()
X_scaled = scaler.fit_transform(X)

# ---------------------------------------
# 4. PCA (Speed Optimization for t-SNE)
# ---------------------------------------
pca = PCA(n_components=30)
X_pca = pca.fit_transform(X_scaled)

print("\nExplained variance by PCA:", np.sum(pca.explained_variance_ratio_))

# ---------------------------------------
# 5. t-SNE
# ---------------------------------------
tsne = TSNE(
    n_components=2,
    perplexity=30,
    learning_rate=200,
    n_iter=1000,
    random_state=42
)

X_tsne = tsne.fit_transform(X_pca)

# ---------------------------------------
# 6. UMAP
# ---------------------------------------
umap_model = umap.UMAP(
    n_neighbors=15,
    min_dist=0.1,
    n_components=2,
    random_state=42
)

X_umap = umap_model.fit_transform(X_scaled)

# ---------------------------------------
# 7. VISUALIZATION
# ---------------------------------------
plt.figure(figsize=(14, 6))

# t-SNE plot
plt.subplot(1, 2, 1)
plt.scatter(X_tsne[:, 0], X_tsne[:, 1], c=pd.factorize(y)[0], s=10)
plt.title("t-SNE Projection")
plt.xlabel("Component 1")
plt.ylabel("Component 2")

# UMAP plot
plt.subplot(1, 2, 2)
plt.scatter(X_umap[:, 0], X_umap[:, 1], c=pd.factorize(y)[0], s=10)
plt.title("UMAP Projection")
plt.xlabel("Component 1")
plt.ylabel("Component 2")

plt.tight_layout()
plt.show()

# ---------------------------------------
# 8. SILHOUETTE SCORES
# ---------------------------------------
# Convert labels to numeric if needed
y_encoded = pd.factorize(y)[0]

tsne_score = silhouette_score(X_tsne, y_encoded)
umap_score = silhouette_score(X_umap, y_encoded)

print("\nSilhouette Score (t-SNE):", tsne_score)
print("Silhouette Score (UMAP):", umap_score)

# ---------------------------------------
# 9. OPTIONAL: IMPROVED UMAP (TUNING)
# ---------------------------------------
umap_tuned = umap.UMAP(
    n_neighbors=30,
    min_dist=0.05,
    metric='cosine',
    n_components=2,
    random_state=42
)

X_umap_tuned = umap_tuned.fit_transform(X_scaled)

plt.figure()
plt.scatter(X_umap_tuned[:, 0], X_umap_tuned[:, 1], c=y_encoded, s=10)
plt.title("Tuned UMAP Projection")
plt.show()

tuned_score = silhouette_score(X_umap_tuned, y_encoded)
print("\nSilhouette Score (Tuned UMAP):", tuned_score)

"""**Vibration Sensor Faults**"""

import numpy as np
import pandas as pd
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import accuracy_score, precision_score, recall_score
import lightgbm as lgb
from sklearn.neural_network import MLPRegressor

# -----------------------------
# Residual Memory Embedding Layer (RMEL)
# -----------------------------
class RMEL:
    def __init__(self, input_dim, hidden_dim=32):
        self.mlp = MLPRegressor(hidden_layer_sizes=(hidden_dim,), max_iter=150, random_state=42)

    def fit(self, X, residuals):
        self.mlp.fit(X, residuals)
        return self.transform(X, residuals)

    def transform(self, X, residuals):
        emb = self.mlp.predict(X).reshape(-1,1)
        Z = X + emb + 0.05*residuals.reshape(-1,1)
        return Z

# -----------------------------
# ResilientGBM++ 2.0
# -----------------------------
class ResilientGBMPlusPlus:
    def __init__(self, n_estimators=150, learning_rate=0.05, max_depth=6, residual_memory=3, minority_class=1):
        self.n_estimators = n_estimators
        self.learning_rate = learning_rate
        self.max_depth = max_depth
        self.residual_memory = residual_memory
        self.minority_class = minority_class
        self.model = None
        self.rm_layer = None

    # RGSS oversampling (simplified)
    def rgss_oversample(self, X, y, residuals):
        idx = np.where(y == self.minority_class)[0]
        if len(idx) == 0: return X, y
        top_idx = idx[np.argsort(np.abs(residuals[idx]))[-max(1,int(0.2*len(idx))):]]
        synth_samples, synth_labels = [], []
        for i in top_idx:
            j = np.random.choice(idx)
            lam = np.random.rand()
            x_new = X[i] + lam*(X[j]-X[i])
            synth_samples.append(x_new)
            synth_labels.append(self.minority_class)
        X_aug = np.vstack([X, np.array(synth_samples)])
        y_aug = np.hstack([y, np.array(synth_labels)])
        return X_aug, y_aug

    # Attention computation (placeholder)
    def compute_attention(self, X):
        alpha = np.mean(np.abs(X), axis=1)
        alpha = alpha / np.max(alpha)
        return alpha

    # Gradient filter (simplified)
    def gradient_filter(self, residuals, tau=0.5):
        return residuals * (1/(1+np.exp(-residuals/tau)))

    # Fit method
    def fit(self, X, y):
        residuals = np.zeros(X.shape[0])
        self.rm_layer = RMEL(input_dim=X.shape[1])
        X_emb = self.rm_layer.fit(X, residuals)

        # Split for validation (10%)
        X_train_emb, X_val_emb, y_train_sub, y_val = train_test_split(
            X_emb, y, test_size=0.1, random_state=42, stratify=y
        )

        # Oversample minority class before LightGBM training
        X_train_aug, y_train_aug = self.rgss_oversample(X_train_emb, y_train_sub, residuals[:len(y_train_sub)])

        # Dataset
        lgb_train = lgb.Dataset(X_train_aug, y_train_aug)
        lgb_val = lgb.Dataset(X_val_emb, y_val, reference=lgb_train)

        params = {
            'objective': 'multiclass' if len(np.unique(y)) > 2 else 'binary',
            'num_class': len(np.unique(y)) if len(np.unique(y)) > 2 else 1,
            'learning_rate': self.learning_rate,
            'max_depth': self.max_depth,
            'num_leaves': 31,
            'reg_lambda': 1.0,
            'reg_alpha': 0.5,
            'class_weight': 'balanced',
            'metric': 'multi_logloss' if len(np.unique(y)) > 2 else 'binary_logloss',
            'verbose': -1
        }

        # Train with early stopping using callback
        self.model = lgb.train(
            params,
            lgb_train,
            num_boost_round=self.n_estimators,
            valid_sets=[lgb_train, lgb_val],
            valid_names=['train','val'],
            callbacks=[lgb.early_stopping(stopping_rounds=20), lgb.log_evaluation(period=0)]
        )

    def predict(self, X):
        X_emb = self.rm_layer.transform(X, np.zeros(X.shape[0]))
        y_pred = self.model.predict(X_emb, num_iteration=self.model.best_iteration)
        if len(y_pred.shape) == 1:
            return (y_pred >= 0.5).astype(int)
        else:
            return np.argmax(y_pred, axis=1)

    def predict_proba(self, X):
        X_emb = self.rm_layer.transform(X, np.zeros(X.shape[0]))
        y_pred = self.model.predict(X_emb, num_iteration=self.model.best_iteration)
        if len(y_pred.shape) == 1:
            return np.vstack([1-y_pred, y_pred]).T
        else:
            return y_pred

# -----------------------------
# Load CSV
# -----------------------------
df = pd.read_csv("/content/Vibration_Dataset.csv")
X = df.iloc[:, :-8].values
y = df.iloc[:, -1].values

X_train, X_test, y_train, y_test = train_test_split(
    X, y, test_size=0.3, random_state=42, stratify=y
)

scaler = StandardScaler()
X_train_scaled = scaler.fit_transform(X_train)
X_test_scaled = scaler.transform(X_test)

# -----------------------------
# Train ResilientGBM++ 2.0
# -----------------------------
model = ResilientGBMPlusPlus(n_estimators=150, learning_rate=0.05, max_depth=6, minority_class=1)
model.fit(X_train_scaled, y_train)

y_pred = model.predict(X_test_scaled)

# -----------------------------
# Metrics
# -----------------------------
acc = accuracy_score(y_test, y_pred)
prec = precision_score(y_test, y_pred, average='macro', zero_division=0)
rec = recall_score(y_test, y_pred, average='macro', zero_division=0)

print(f"Accuracy: {acc:.4f}")
