# Compute specificity for each class
# -----------------------------
specificities = []
for i, cls in enumerate(classes):
    TP = cm[i, i]
    FP = cm[:, i].sum() - TP
    FN = cm[i, :].sum() - TP
    TN = cm.sum() - (TP + FP + FN)
    spec = TN / (TN + FP) if (TN + FP) > 0 else 0
    specificities.append(spec)

# Average specificity
avg_specificity = np.mean(specificities)


