import numpy as np
import pandas as pd
from sklearn.metrics import silhouette_samples
from scipy.spatial.distance import cdist

def analyze_embedding(X_embedded, y, method_name="Embedding"):

    print(f"\n{'='*50}")
    print(f"{method_name} INSIGHTS")
    print(f"{'='*50}")

    # ---------------------------------------
    # Encode labels safely
    # ---------------------------------------
    y_encoded, class_names = pd.factorize(y)
    unique_classes = np.unique(y_encoded)

    # Convert class names to string (CRITICAL FIX)
    class_names = [str(c) for c in class_names]

    # ---------------------------------------
    # 1. SILHOUETTE ANALYSIS (per class)
    # ---------------------------------------
    sil_samples = silhouette_samples(X_embedded, y_encoded)

    class_silhouette = {}
    for cls in unique_classes:
        class_silhouette[class_names[cls]] = sil_samples[y_encoded == cls].mean()

    print("\n📊 Average Silhouette Score per Class:")
    for k, v in sorted(class_silhouette.items(), key=lambda x: x[1]):
        print(f"{k:35s}: {v:.4f}")

    # ---------------------------------------
    # 2. CLUSTER CENTROIDS
    # ---------------------------------------
    centroids = {}
    for cls in unique_classes:
        centroids[cls] = X_embedded[y_encoded == cls].mean(axis=0)

    # ---------------------------------------
    # 3. INTER-CLASS DISTANCE MATRIX
    # ---------------------------------------
    centroid_matrix = np.array([centroids[c] for c in unique_classes])
    dist_matrix = cdist(centroid_matrix, centroid_matrix)

    print("\n📏 Closest Class Pairs (Most Confused):")
    pairs = []
    for i in range(len(unique_classes)):
        for j in range(i + 1, len(unique_classes)):
            pairs.append((
                class_names[i],
                class_names[j],
                dist_matrix[i][j]
            ))

    pairs_sorted = sorted(pairs, key=lambda x: x[2])

    for p in pairs_sorted[:5]:
        print(f"{p[0]:30s} <--> {p[1]:30s} | Distance: {p[2]:.4f}")

    # ---------------------------------------
    # 4. INTRA-CLASS COMPACTNESS
    # ---------------------------------------
    compactness = {}
    for cls in unique_classes:
        points = X_embedded[y_encoded == cls]
        centroid = centroids[cls]
        distances = np.linalg.norm(points - centroid, axis=1)
        compactness[class_names[cls]] = distances.mean()

    print("\n📦 Cluster Compactness (Lower = Tighter):")
    for k, v in sorted(compactness.items(), key=lambda x: x[1]):
        print(f"{k:35s}: {v:.4f}")

    # ---------------------------------------
    # 5. OVERLAP SCORE (Improved Stability)
    # ---------------------------------------
    overlap_scores = {}

    for cls in unique_classes:
        own_points = X_embedded[y_encoded == cls]
        other_points = X_embedded[y_encoded != cls]

        # Avoid heavy computation for large datasets
        if len(own_points) > 500:
            own_points = own_points[np.random.choice(len(own_points), 500, replace=False)]
        if len(other_points) > 500:
            other_points = other_points[np.random.choice(len(other_points), 500, replace=False)]

        dist_to_own = np.mean(cdist(own_points, own_points))
        dist_to_other = np.mean(cdist(own_points, other_points))

        overlap_scores[class_names[cls]] = dist_to_other / (dist_to_own + 1e-8)

    print("\n⚠️ Overlap Score (Lower = More Overlap):")
    for k, v in sorted(overlap_scores.items(), key=lambda x: x[1]):
        print(f"{k:35s}: {v:.4f}")

    # ---------------------------------------
    # 6. FINAL INSIGHT SUMMARY
    # ---------------------------------------
    print("\n✅ Insight Summary:")
    print("- Low silhouette → weak separability")
    print("- Small centroid distance → high confusion risk")
    print("- High compactness → scattered clusters")
    print("- Low overlap score → strong overlap with other classes")


# ---------------------------------------
# RUN ANALYSIS
# ---------------------------------------

# Make sure X_tsne, X_umap, y are defined
analyze_embedding(X_tsne, y, "t-SNE")
analyze_embedding(X_umap, y, "UMAP")

import pandas as pd
import numpy as np
import seaborn as sns
import matplotlib.pyplot as plt
from scipy.cluster import hierarchy
from scipy.spatial.distance import squareform

def plot_top_correlated_features(df, top_n=20, method='pearson', figsize=(12, 10)):
    """
    Create a correlation heatmap for the top N most inter-correlated features.

    Parameters:
    -----------
    df : pandas.DataFrame
        Input dataframe with features
    top_n : int
        Number of top inter-correlated features to select
    method : str
        Correlation method ('pearson', 'spearman', 'kendall')
    figsize : tuple
        Figure size (width, height)
    """

    # Calculate correlation matrix
    corr_matrix = df.corr(method=method).abs()

    # Create a mask for the upper triangle
    mask = np.triu(np.ones_like(corr_matrix, dtype=bool), k=1)

    # Get the upper triangle correlations (excluding diagonal)
    upper_tri = corr_matrix.where(mask).stack().reset_index()
    upper_tri.columns = ['feature1', 'feature2', 'correlation']

    # Sort by correlation strength and get unique features
    # First, get the strongest correlations
    top_correlations = upper_tri.sort_values('correlation', ascending=False).head(top_n * 2)

    # Get unique features from these top correlations
    unique_features = pd.unique(top_correlations[['feature1', 'feature2']].values.ravel())

    # If we have more than top_n features, take the ones with highest average correlation
    if len(unique_features) > top_n:
        # Calculate average correlation for each feature
        feature_avg_corr = []
        for feature in unique_features:
            feature_corrs = corr_matrix[feature].sort_values(ascending=False)
            # Exclude self-correlation
            feature_corrs = feature_corrs[feature_corrs.index != feature]
            avg_corr = feature_corrs.mean()
            feature_avg_corr.append((feature, avg_corr))

        # Sort by average correlation and take top_n
        feature_avg_corr.sort(key=lambda x: x[1], reverse=True)
        selected_features = [f[0] for f in feature_avg_corr[:top_n]]
    else:
        selected_features = list(unique_features)

    # Subset the correlation matrix
    sub_corr = corr_matrix.loc[selected_features, selected_features]

    # Create heatmap
    plt.figure(figsize=figsize)

    # Option 1: Basic heatmap
    sns.heatmap(sub_corr,
                annot=True,           # Show correlation values
                cmap='RdBu_r',        # Color map (red for positive, blue for negative)
                center=0,             # Center colormap at 0
                vmin=-1, vmax=1,      # Correlation range
                square=True,          # Square cells
                linewidths=0.5,       # Cell borders
                cbar_kws={"shrink": 0.8, "label": f"{method.capitalize()} Correlation"},
                fmt='.2f',            # 2 decimal places
                annot_kws={'size': 8}) # Annotation font size

    plt.title(f'Correlation Heatmap - Top {len(selected_features)} Inter-correlated Features',
              fontsize=14, fontweight='bold')
    plt.xticks(rotation=45, ha='right', fontsize=10)
    plt.yticks(rotation=0, fontsize=10)
    plt.tight_layout()
    plt.show()

    return sub_corr, selected_features

def plot_clustered_correlation_heatmap(df, top_n=20, method='pearson', figsize=(12, 10)):
    """
    Create a clustered correlation heatmap (with dendrograms) for top inter-correlated features.

    Parameters:
    -----------
    df : pandas.DataFrame
        Input dataframe with features
    top_n : int
        Number of top inter-correlated features to select
    method : str
        Correlation method ('pearson', 'spearman', 'kendall')
    figsize : tuple
        Figure size (width, height)
    """

    # Calculate correlation matrix
    corr_matrix = df.corr(method=method).abs()

    # Create mask for upper triangle
    mask = np.triu(np.ones_like(corr_matrix, dtype=bool), k=1)

    # Get top correlations (same as above)
    upper_tri = corr_matrix.where(mask).stack().reset_index()
    upper_tri.columns = ['feature1', 'feature2', 'correlation']
    top_correlations = upper_tri.sort_values('correlation', ascending=False).head(top_n * 2)
    unique_features = pd.unique(top_correlations[['feature1', 'feature2']].values.ravel())

    if len(unique_features) > top_n:
        feature_avg_corr = []
        for feature in unique_features:
            feature_corrs = corr_matrix[feature].sort_values(ascending=False)
            feature_corrs = feature_corrs[feature_corrs.index != feature]
            avg_corr = feature_corrs.mean()
            feature_avg_corr.append((feature, avg_corr))

        feature_avg_corr.sort(key=lambda x: x[1], reverse=True)
        selected_features = [f[0] for f in feature_avg_corr[:top_n]]
    else:
        selected_features = list(unique_features)

    # Subset correlation matrix
    sub_corr = corr_matrix.loc[selected_features, selected_features]

    # Create clustered heatmap
    plt.figure(figsize=figsize)

    # Generate clustering
    linkage = hierarchy.linkage(squareform(1 - sub_corr.values), method='average')

    # Create clustermap
    g = sns.clustermap(sub_corr,
                       method='average',      # Clustering method
                       cmap='RdBu_r',         # Color map
                       center=0,              # Center at 0
                       vmin=-1, vmax=1,       # Correlation range
                       annot=True,            # Show values
                       fmt='.2f',             # 2 decimal places
                       annot_kws={'size': 8}, # Annotation font size
                       figsize=figsize,
                       cbar_kws={"shrink": 0.8, "label": f"{method.capitalize()} Correlation"},
                       dendrogram_ratio=0.15,  # Dendrogram size
                       cbar_pos=(0.02, 0.8, 0.05, 0.18))  # Colorbar position

    g.ax_heatmap.set_xlabel('Features', fontsize=11)
    g.ax_heatmap.set_ylabel('Features', fontsize=11)
    g.ax_heatmap.set_title(f'Clustered Correlation Heatmap - Top {len(selected_features)} Features',
                          fontsize=14, fontweight='bold', pad=20)

    plt.tight_layout()
    plt.show()

    return sub_corr, selected_features

