def generate_correlation_insights(df):
    """
    Generate natural language insights from correlation matrix.
    """
    corr_matrix = df.corr()
    upper = corr_matrix.where(np.triu(np.ones(corr_matrix.shape), k=1).astype(bool))
    corr_values = upper.stack()

    insights = []

    # Overall assessment
    if corr_values.abs().mean() < 0.2:
        insights.append("• Overall, features show weak linear relationships.")
    elif corr_values.abs().mean() < 0.5:
        insights.append("• Features show moderate linear relationships overall.")
    else:
        insights.append("• Strong linear relationships exist between many features.")

    # Strong correlations
    strong_corr = corr_values[corr_values.abs() > 0.7]
    if len(strong_corr) > 0:
        insights.append(f"• Found {len(strong_corr)} pairs with strong correlation (>0.7).")
        top_pair = strong_corr.abs().idxmax()
        insights.append(f"  Strongest: {top_pair[0]} ↔ {top_pair[1]} ({corr_values[top_pair]:.3f})")

    # Multicollinearity warning
    high_corr_features = []
    for col in corr_matrix.columns:
        others = corr_matrix[col][corr_matrix[col].index != col]
        if (others.abs() > 0.8).sum() > 2:
            high_corr_features.append(col)

    if high_corr_features:
        insights.append(f"• Features with potential multicollinearity: {', '.join(high_corr_features)}")
        insights.append("  Consider feature selection or dimensionality reduction.")

    # Negative correlations
    neg_corr = corr_values[corr_values < -0.5]
    if len(neg_corr) > 0:
        insights.append(f"• Found {len(neg_corr)} strong negative correlations.")

    print("\n".join(insights))
    return insights

# Usage
insights = generate_correlation_insights(df)

import pandas as pd
import numpy as np
import seaborn as sns
import matplotlib.pyplot as plt

def describe_correlation_matrix(df, method='pearson'):
    """
    Generate comprehensive description of correlation matrix.

    Parameters:
    -----------
    df : pandas.DataFrame
        Input dataframe
    method : str
        Correlation method ('pearson', 'spearman', 'kendall')
    """

    # Calculate correlation matrix
    corr_matrix = df.corr(method=method)

    # Get upper triangle without diagonal
    upper_triangle = corr_matrix.where(np.triu(np.ones(corr_matrix.shape), k=1).astype(bool))
    correlations = upper_triangle.stack()

    print("="*60)
    print("CORRELATION MATRIX DESCRIPTION")
    print("="*60)

    # Basic statistics
    print(f"\n1. BASIC STATISTICS:")
    print(f"   Number of features: {corr_matrix.shape[0]}")
    print(f"   Number of correlations: {len(correlations)}")
    print(f"   Mean correlation: {correlations.mean():.4f}")
    print(f"   Std deviation: {correlations.std():.4f}")
    print(f"   Min correlation: {correlations.min():.4f}")
    print(f"   Max correlation: {correlations.max():.4f}")

    # Distribution of correlations
    print(f"\n2. CORRELATION DISTRIBUTION:")
    percentiles = [0, 10, 25, 50, 75, 90, 95, 99, 100]
    for p in percentiles:
        value = np.percentile(correlations, p)
        print(f"   {p:3d}th percentile: {value:.4f}")

    # Categorize correlations
    strong_positive = correlations[correlations > 0.7]
    moderate_positive = correlations[(correlations > 0.4) & (correlations <= 0.7)]
    weak_positive = correlations[(correlations > 0) & (correlations <= 0.4)]
    weak_negative = correlations[(correlations < 0) & (correlations >= -0.4)]
    moderate_negative = correlations[(correlations < -0.4) & (correlations >= -0.7)]
    strong_negative = correlations[correlations < -0.7]

    print(f"\n3. CORRELATION STRENGTH CATEGORIZATION:")
    print(f"   Strong positive (> 0.7): {len(strong_positive)} ({len(strong_positive)/len(correlations)*100:.1f}%)")
    print(f"   Moderate positive (0.4-0.7): {len(moderate_positive)} ({len(moderate_positive)/len(correlations)*100:.1f}%)")
    print(f"   Weak positive (0-0.4): {len(weak_positive)} ({len(weak_positive)/len(correlations)*100:.1f}%)")
    print(f"   Weak negative (-0.4-0): {len(weak_negative)} ({len(weak_negative)/len(correlations)*100:.1f}%)")
    print(f"   Moderate negative (-0.7 to -0.4): {len(moderate_negative)} ({len(moderate_negative)/len(correlations)*100:.1f}%)")
    print(f"   Strong negative (< -0.7): {len(strong_negative)} ({len(strong_negative)/len(correlations)*100:.1f}%)")

    return corr_matrix

def get_top_correlations(corr_matrix, n=10, absolute=True):
    """
    Get top N strongest correlations.

    Parameters:
    -----------
    corr_matrix : pandas.DataFrame
        Correlation matrix
    n : int
        Number of top correlations to return
    absolute : bool
        If True, consider absolute values; if False, consider actual values
    """

    # Get upper triangle without diagonal
    upper_triangle = corr_matrix.where(np.triu(np.ones(corr_matrix.shape), k=1).astype(bool))
    correlations = upper_triangle.stack()

    if absolute:
        correlations_abs = correlations.abs()
        top_correlations = correlations_abs.nlargest(n)
        print(f"\n4. TOP {n} STRONGEST CORRELATIONS (absolute values):")
        for (feat1, feat2), value in top_correlations.items():
            actual_value = correlations[feat1, feat2]
            print(f"   {feat1} ↔ {feat2}: {actual_value:.4f} (|r| = {value:.4f})")
    else:
        top_positive = correlations.nlargest(n)
        top_negative = correlations.nsmallest(n)

        print(f"\n4. TOP {n} POSITIVE CORRELATIONS:")
        for (feat1, feat2), value in top_positive.items():
            print(f"   {feat1} ↔ {feat2}: {value:.4f}")

        print(f"\n   TOP {n} NEGATIVE CORRELATIONS:")
        for (feat1, feat2), value in top_negative.items():
            print(f"   {feat1} ↔ {feat2}: {value:.4f}")

    return correlations

def find_highly_correlated_features(corr_matrix, threshold=0.7):
    """
    Find pairs of features with correlation above threshold.

    Parameters:
    -----------
    corr_matrix : pandas.DataFrame
        Correlation matrix
    threshold : float
        Correlation threshold
    """

    # Get upper triangle without diagonal
    upper_triangle = corr_matrix.where(np.triu(np.ones(corr_matrix.shape), k=1).astype(bool))
    correlations = upper_triangle.stack()

    # Find high correlations
    high_corr = correlations[correlations.abs() > threshold]

    print(f"\n5. HIGHLY CORRELATED FEATURES (|r| > {threshold}):")
    if len(high_corr) == 0:
        print(f"   No features with correlation > {threshold}")
    else:
        for (feat1, feat2), value in high_corr.sort_values(ascending=False).items():
            print(f"   {feat1} ↔ {feat2}: {value:.4f}")

    return high_corr

def feature_summary_statistics(df, corr_matrix):
    """
    Get correlation summary for each feature.

    Parameters:
    -----------
    df : pandas.DataFrame
        Original dataframe
    corr_matrix : pandas.DataFrame
        Correlation matrix
    """

    summary = pd.DataFrame(index=corr_matrix.columns)

    # For each feature, calculate statistics
    for feature in corr_matrix.columns:
        # Get correlations with other features (excluding self)
        other_corrs = corr_matrix[feature][corr_matrix[feature].index != feature]

        summary.loc[feature, 'mean_correlation'] = other_corrs.mean()
        summary.loc[feature, 'std_correlation'] = other_corrs.std()
        summary.loc[feature, 'max_correlation'] = other_corrs.max()
        summary.loc[feature, 'min_correlation'] = other_corrs.min()
        summary.loc[feature, 'correlated_features_>0.5'] = (other_corrs.abs() > 0.5).sum()
        summary.loc[feature, 'avg_abs_correlation'] = other_corrs.abs().mean()

    print("\n6. FEATURE-WISE CORRELATION SUMMARY:")
    print(summary.round(4).to_string())

    return summary

def visualize_correlation_summary(corr_matrix):
    """
    Create visualizations to describe the correlation matrix.

    Parameters:
    -----------
    corr_matrix : pandas.DataFrame
        Correlation matrix
    """

    # Get upper triangle correlations
    upper_triangle = corr_matrix.where(np.triu(np.ones(corr_matrix.shape), k=1).astype(bool))
    correlations = upper_triangle.stack()

    # Create figure with subplots
    fig, axes = plt.subplots(2, 2, figsize=(14, 10))

    # 1. Distribution of correlations
    axes[0, 0].hist(correlations, bins=30, edgecolor='black', alpha=0.7, color='steelblue')
    axes[0, 0].axvline(x=0, color='red', linestyle='--', alpha=0.5)
    axes[0, 0].set_xlabel('Correlation Coefficient')
    axes[0, 0].set_ylabel('Frequency')
    axes[0, 0].set_title(f'Distribution of Correlations (n={len(correlations)})')
    axes[0, 0].grid(True, alpha=0.3)

    # 2. Box plot of correlations by strength category
    categories = []
    cat_names = []
    for corr in correlations:
        if corr > 0.7:
            categories.append('Strong\nPositive')
        elif corr > 0.4:
            categories.append('Moderate\nPositive')
        elif corr > 0:
            categories.append('Weak\nPositive')
        elif corr > -0.4:
            categories.append('Weak\nNegative')
        elif corr > -0.7:
            categories.append('Moderate\nNegative')
        else:
            categories.append('Strong\nNegative')

    cat_data = {name: [correlations.iloc[i] for i, c in enumerate(categories) if c == name]
                for name in set(categories)}

    positions = range(len(cat_data))
    axes[0, 1].boxplot(cat_data.values(), positions=positions, labels=cat_data.keys())
    axes[0, 1].set_ylabel('Correlation Coefficient')
    axes[0, 1].set_title('Correlation Distribution by Strength')
    axes[0, 1].axhline(y=0, color='red', linestyle='--', alpha=0.5)
    axes[0, 1].grid(True, alpha=0.3)

    # 3. Heatmap of correlation matrix
    im = axes[1, 0].imshow(corr_matrix, cmap='RdBu_r', vmin=-1, vmax=1, aspect='auto')
    axes[1, 0].set_xticks(range(len(corr_matrix.columns)))
    axes[1, 0].set_yticks(range(len(corr_matrix.columns)))
    axes[1, 0].set_xticklabels(corr_matrix.columns, rotation=45, ha='right', fontsize=8)
    axes[1, 0].set_yticklabels(corr_matrix.columns, fontsize=8)
    axes[1, 0].set_title('Correlation Matrix Heatmap')
    plt.colorbar(im, ax=axes[1, 0], label='Correlation Coefficient')

    # 4. Feature average correlation bar plot
    avg_correlations = corr_matrix.mean(axis=1)
    colors = ['red' if x < 0 else 'green' for x in avg_correlations]
    axes[1, 1].barh(range(len(avg_correlations)), avg_correlations.values, color=colors, alpha=0.7)
    axes[1, 1].set_yticks(range(len(avg_correlations)))
    axes[1, 1].set_yticklabels(avg_correlations.index, fontsize=8)
    axes[1, 1].set_xlabel('Average Correlation with Other Features')
    axes[1, 1].set_title('Feature-wise Average Correlation')
    axes[1, 1].axvline(x=0, color='black', linestyle='-', alpha=0.5)
    axes[1, 1].grid(True, alpha=0.3)

    plt.tight_layout()
    plt.show()

# Complete example with all functions
