import numpy as np
import pandas as pd
import lightgbm as lgb
import matplotlib.pyplot as plt

from sklearn.model_selection import StratifiedKFold, train_test_split
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import accuracy_score, precision_score, recall_score, confusion_matrix
from sklearn.neural_network import MLPRegressor

# -----------------------------
# Residual Memory Embedding Layer (RMEL)
# -----------------------------
class RMEL:
    def __init__(self, input_dim, hidden_dim=32):
        self.mlp = MLPRegressor(hidden_layer_sizes=(hidden_dim,), max_iter=150, random_state=42)

    def fit(self, X, residuals):
        self.mlp.fit(X, residuals)
        return self.transform(X, residuals)

    def transform(self, X, residuals):
        emb = self.mlp.predict(X).reshape(-1, 1)
        Z = X + emb + 0.05 * residuals.reshape(-1, 1)
        return Z


# -----------------------------
# ResilientGBM++ 2.0
# -----------------------------
class ResilientGBMPlusPlus:
    def __init__(self, n_estimators=150, learning_rate=0.05, max_depth=6, minority_class=1):
        self.n_estimators = n_estimators
        self.learning_rate = learning_rate
        self.max_depth = max_depth
        self.minority_class = minority_class
        self.model = None
        self.rm_layer = None

    def rgss_oversample(self, X, y, residuals):
        idx = np.where(y == self.minority_class)[0]
        if len(idx) == 0:
            return X, y

        top_idx = idx[np.argsort(np.abs(residuals[idx]))[-max(1, int(0.2 * len(idx))):]]

        synth_samples, synth_labels = [], []
        for i in top_idx:
            j = np.random.choice(idx)
            lam = np.random.rand()
            x_new = X[i] + lam * (X[j] - X[i])
            synth_samples.append(x_new)
            synth_labels.append(self.minority_class)

        X_aug = np.vstack([X, np.array(synth_samples)])
        y_aug = np.hstack([y, np.array(synth_labels)])

        return X_aug, y_aug

    def compute_attention(self, X):
        alpha = np.mean(np.abs(X), axis=1)
        alpha = alpha / np.max(alpha)
        return alpha

    def gradient_filter(self, residuals, tau=0.5):
        return residuals * (1/(1+np.exp(-residuals/tau)))

    def fit(self, X, y):
        residuals = np.zeros(X.shape[0])

        self.rm_layer = RMEL(input_dim=X.shape[1])
        X_emb = self.rm_layer.fit(X, residuals)

        X_train_emb, X_val_emb, y_train_sub, y_val = train_test_split(
            X_emb, y, test_size=0.1, random_state=42, stratify=y
        )

        X_train_aug, y_train_aug = self.rgss_oversample(
            X_train_emb, y_train_sub, residuals[:len(y_train_sub)]
        )

        lgb_train = lgb.Dataset(X_train_aug, y_train_aug)
        lgb_val = lgb.Dataset(X_val_emb, y_val, reference=lgb_train)

        params = {
            'objective': 'multiclass' if len(np.unique(y)) > 2 else 'binary',
            'num_class': len(np.unique(y)) if len(np.unique(y)) > 2 else 1,
            'learning_rate': self.learning_rate,
            'max_depth': self.max_depth,
            'num_leaves': 31,
            'reg_lambda': 1.0,
            'reg_alpha': 0.5,
            'class_weight': 'balanced',
            'metric': 'multi_logloss' if len(np.unique(y)) > 2 else 'binary_logloss',
            'verbose': -1
        }

        self.model = lgb.train(
            params,
            lgb_train,
            num_boost_round=self.n_estimators,
            valid_sets=[lgb_train, lgb_val],
            valid_names=['train', 'val'],
            callbacks=[lgb.early_stopping(20), lgb.log_evaluation(0)]
        )

    def predict(self, X):
        X_emb = self.rm_layer.transform(X, np.zeros(X.shape[0]))
        y_pred = self.model.predict(X_emb, num_iteration=self.model.best_iteration)

        if len(y_pred.shape) == 1:
            return (y_pred >= 0.5).astype(int)
        else:
            return np.argmax(y_pred, axis=1)


# -----------------------------
# Load Dataset
# -----------------------------
df = pd.read_csv("/content/Vibration_Dataset.csv")

X = df.iloc[:, :-8].values
y = df.iloc[:, -4].values

# -----------------------------
# 5-Fold Cross Validation
# -----------------------------
kf = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)

acc_list, prec_list, rec_list, spec_list = [], [], [], []
fpr_list, fnr_list = [], []

all_y_true = []
all_y_pred = []

for fold, (train_idx, test_idx) in enumerate(kf.split(X, y)):
    print(f"\n========== Fold {fold+1} ==========")

    X_train, X_test = X[train_idx], X[test_idx]
    y_train, y_test = y[train_idx], y[test_idx]

    scaler = StandardScaler()
    X_train = scaler.fit_transform(X_train)
    X_test = scaler.transform(X_test)

    model = ResilientGBMPlusPlus()
    model.fit(X_train, y_train)

    y_pred = model.predict(X_test)

    all_y_true.extend(y_test)
    all_y_pred.extend(y_pred)

    # Metrics
    acc = accuracy_score(y_test, y_pred)
    prec = precision_score(y_test, y_pred, average='macro', zero_division=0)
    rec = recall_score(y_test, y_pred, average='macro', zero_division=0)

    cm = confusion_matrix(y_test, y_pred, labels=np.unique(y))
    classes = np.unique(y)

    spec_per_class = []
    fpr_per_class = []
    fnr_per_class = []

    for i in range(len(classes)):
        TP = cm[i, i]
        FP = cm[:, i].sum() - TP
        FN = cm[i, :].sum() - TP
        TN = cm.sum() - (TP + FP + FN)

        spec = TN / (TN + FP) if (TN + FP) > 0 else 0
        fpr = FP / (FP + TN) if (FP + TN) > 0 else 0
        fnr = FN / (FN + TP) if (FN + TP) > 0 else 0

        spec_per_class.append(spec)
        fpr_per_class.append(fpr)
        fnr_per_class.append(fnr)

    spec = np.mean(spec_per_class)
    fpr = np.mean(fpr_per_class)
    fnr = np.mean(fnr_per_class)

    acc_list.append(acc)
    prec_list.append(prec)
    rec_list.append(rec)
    spec_list.append(spec)
    fpr_list.append(fpr)
    fnr_list.append(fnr)

    print(f"Accuracy: {acc:.4f}")
    print(f"Precision: {prec:.4f}")
    print(f"Sensitivity: {rec:.4f}")
    print(f"Specificity: {spec:.4f}")
    print(f"FPR: {fpr:.4f}")
    print(f"FNR: {fnr:.4f}")

# -----------------------------
# FINAL RESULTS
# -----------------------------
print("\n========== FINAL RESULTS ==========")
print(f"Accuracy:    {np.mean(acc_list):.4f} ± {np.std(acc_list):.4f}")
print(f"Precision:   {np.mean(prec_list):.4f} ± {np.std(prec_list):.4f}")
print(f"Sensitivity: {np.mean(rec_list):.4f} ± {np.std(rec_list):.4f}")
print(f"Specificity: {np.mean(spec_list):.4f} ± {np.std(spec_list):.4f}")
print(f"FPR:         {np.mean(fpr_list):.4f} ± {np.std(fpr_list):.4f}")
print(f"FNR:         {np.mean(fnr_list):.4f} ± {np.std(fnr_list):.4f}")

# -----------------------------
# FINAL CONFUSION MATRIX (COLORFUL)
# -----------------------------
cm = confusion_matrix(all_y_true, all_y_pred)
classes = np.unique(y)

print("\n========== FINAL CONFUSION MATRIX ==========")
print(cm)

plt.figure(figsize=(7,6))
plt.imshow(cm, interpolation='nearest')
plt.title("Radiation-Induced Degradation", fontsize=14, fontweight='bold')
plt.colorbar()

tick_marks = np.arange(len(classes))
plt.xticks(tick_marks, classes)
plt.yticks(tick_marks, classes)

plt.xlabel("Predicted Label")
plt.ylabel("True Label")

for i in range(cm.shape[0]):
    for j in range(cm.shape[1]):
        plt.text(j, i, str(cm[i, j]),
                 ha="center", va="center",
                 fontsize=14, fontweight='bold',
                 color="red" if cm[i, j] > cm.max()/2 else "orange")

plt.tight_layout()
plt.show()

