plt.figure(figsize=(15, 8), dpi=300)  # 🔥 high resolution

bars1 = plt.barh(
    x - 0.2,
    top_features['Gain (%)'],
    height=0.4,
    label='Gain (%)'
)

bars2 = plt.barh(
    x + 0.2,
    top_features['Split (%)'],
    height=0.4,
    label='Split (%)'
)

# 🔥 Bold & larger ticks
plt.yticks(x, top_features['Feature'], fontsize=12, fontweight='bold')
