plt.gca().invert_yaxis()

# 🔥 Bold labels
plt.xlabel("Importance (%)", fontsize=16, fontweight='bold')
plt.ylabel("Features", fontsize=16, fontweight='bold')

# 🔥 Bold title
plt.title(
    "ResilientGBM Feature Importance (Gas Leakage)",
    fontsize=18,
    fontweight='bold'
)

# 🔥 Legend styling
plt.legend(fontsize=12)

# -----------------------------
# ADD VALUE LABELS (BOLD + CLEAR)
# -----------------------------
for bar in bars1:
    width = bar.get_width()
    plt.text(
        width + 0.3,
        bar.get_y() + bar.get_height()/2,
        f"{width:.2f}",
        va='center',
        fontsize=11,
        fontweight='bold'
    )

for bar in bars2:
    width = bar.get_width()
    plt.text(
        width + 0.3,
        bar.get_y() + bar.get_height()/2,
        f"{width:.2f}",
        va='center',
        fontsize=11,
        fontweight='bold'
    )

# 🔥 Grid for readability
plt.grid(axis='x', linestyle='--', alpha=0.5)

plt.tight_layout()
plt.show()

