from PIL import Image, ImageEnhance

# ---------------------------------------------------
# LOAD IMAGES
# ---------------------------------------------------
image_files = [
    "3 signal drift.png",
    "3 gas leakage.png",
    "3 High Noise Level.png",
    "3 Radiation-Induced Degradation.png",
    "3 Thermal Drift.png",
    "3 Sensor Aging (Degradation).png",
    "3 Offset Bias.png",
    "3 Wiring Reversal.png"
]

images = [Image.open(img).convert("RGB") for img in image_files]

# ---------------------------------------------------
# SETTINGS (ULTRA HIGH QUALITY)
# ---------------------------------------------------
cols = 2
rows = 4

target_width = 1000   # 🔥 increased
target_height = 500   # 🔥 increased

#padding = 80          # more spacing

# ---------------------------------------------------
# RESIZE + ENHANCE
# ---------------------------------------------------
resized_images = []

for img in images:
    img.thumbnail((target_width, target_height), Image.LANCZOS)

    canvas = Image.new("RGB", (target_width, target_height), (255, 255, 255))

    x = (target_width - img.width) // 2
    y = (target_height - img.height) // 2
    canvas.paste(img, (x, y))

    # 🔥 Enhance sharpness
    canvas = ImageEnhance.Sharpness(canvas).enhance(2.0)

    # 🔥 Slight contrast boost
    canvas = ImageEnhance.Contrast(canvas).enhance(1.1)

    resized_images.append(canvas)

# ---------------------------------------------------
# LARGE CANVAS
# ---------------------------------------------------
total_width = cols * target_width + (cols - 1) * padding
total_height = rows * target_height + (rows - 1) * padding

combined = Image.new("RGB", (total_width, total_height), (255, 255, 255))

# ---------------------------------------------------
# PASTE
# ---------------------------------------------------
for i, img in enumerate(resized_images):
    x = (i % cols) * (target_width + padding)
    y = (i // cols) * (target_height + padding)
    combined.paste(img, (x, y))

# ---------------------------------------------------
# SAVE (VERY HIGH QUALITY)
# ---------------------------------------------------
combined.save(
    "combined3_ULTRA.png",
    dpi=(900, 900),   # 🔥 top-tier journal quality
    quality=200,
    subsampling=0
)

combined.show()

